const input = $input.first().json;
const counters = { total: input.expected_cases.length, auto_validated: 0, auto_correct: 0, ambiguous: 0, unresolved: 0, errors: 0 };
const errors = [];
for (const expected of input.expected_cases || []) {
  const actual = input.actual_results_by_case_id[expected.case_id] || { decision: 'missing' };
  if (actual.decision === 'matched') counters.auto_validated += 1;
  if (actual.decision === 'matched' && expected.expected_decision === 'matched' && (!expected.expected_siret || expected.expected_siret === actual.siret)) counters.auto_correct += 1;
  if (actual.decision === 'ambiguous') counters.ambiguous += 1;
  if (actual.decision === 'unresolved') counters.unresolved += 1;
  const wrongAuto = actual.decision === 'matched' && (expected.expected_decision !== 'matched' || (expected.expected_siret && actual.siret !== expected.expected_siret));
  if (wrongAuto || actual.decision === 'missing') { counters.errors += 1; errors.push({ case_id: expected.case_id, stratum: expected.stratum, expected, actual, category: wrongAuto ? 'false_auto_match' : 'missing_result' }); }
}
const auto_precision = counters.auto_validated ? counters.auto_correct / counters.auto_validated : null;
const coverage = counters.total ? counters.auto_validated / counters.total : 0;
const ambiguity_rate = counters.total ? counters.ambiguous / counters.total : 0;
const recommendation = auto_precision !== null && auto_precision >= 0.9 ? 'go_to_scoring' : 'raise_threshold_or_review_rules';
return [{ json: { ...input, benchmark_report: { counters, auto_precision, coverage, ambiguity_rate, errors, recommendation, pappers_go: 'only_if_free_or_budget_approved', llm_go: 'not_v1' } } }];
